1	import { open } from "@tauri-apps/plugin-dialog";
2	import { useEffect, useMemo, useState } from "react";
3	import { useProfiles } from "@/features/profiles/hooks/profiles-context";
4	import { useSshKey } from "@/features/sync/hooks/use-ssh-key";
5	import { Button } from "@/shared/ui/button";
6	import { Input } from "@/shared/ui/input";
7	import { GitSettingsCard } from "./git-settings-card";
8	import { ProfileManagerDialog } from "./profile-manager-dialog";
9	import {
10	  SettingsActionRow,
11	  SettingsCard,
12	  SettingsErrorText,
13	  SettingsField,
14	  SettingsHelpText,
15	  SettingsSection,
16	  SettingsSelect,
17	} from "../settings-ui";
18	
19	export function SettingsProfileSection() {
20	  const {
21	    profiles,
22	    activeProfileId,
23	    activeProfileNotesRoot,
24	    profilesBusy,
25	    profilesError,
26	    switchProfile,
27	    createProfile,
28	    updateProfile,
29	    deleteProfile,
30	    setProfileNotesRoot,
31	    syncSettings,
32	    updateSyncSettings,
33	  } = useProfiles();
34	  const [notesRootInput, setNotesRootInput] = useState("");
35	  const [profileManagerOpen, setProfileManagerOpen] = useState(false);
36	
37	  const activeProfile = useMemo(
38	    () => profiles.find((profile) => profile.id === activeProfileId) ?? null,
39	    [activeProfileId, profiles]
40	  );
41	
42	  useEffect(() => {
43	    setNotesRootInput(activeProfile?.notes_root ?? "");
44	  }, [activeProfile?.notes_root]);
45	
46	  const { sshPublicKey, sshBusy, sshError, generateSshKey, deleteSshKey } =
47	    useSshKey();
48	
49	  const chooseWorkingDirectory = async () => {
50	    try {
51	      const selected = await open({
52	        directory: true,
53	        multiple: false,
54	        defaultPath: notesRootInput || activeProfileNotesRoot || undefined,
55	        title: "Select profile notes folder",
56	      });
57	      if (typeof selected === "string" && selected.trim()) {
58	        setNotesRootInput(selected);
59	      }
60	    } catch (error) {
61	      console.error("Failed to pick working directory", error);
62	    }
63	  };
64	
65	  return (
66	    <SettingsSection title="Profile">
67	      <SettingsCard>
68	        <SettingsField label="Active profile">
69	          <div className="flex flex-wrap items-center gap-2">
70	            <SettingsSelect
71	              className="min-w-[220px] flex-1"
72	              value={activeProfileId ?? ""}
73	              onChange={(event) => void switchProfile(event.target.value)}
74	              disabled={profilesBusy || profiles.length === 0}
75	            >
76	              {profiles.length === 0 ? <option value="">No profiles</option> : null}
77	              {profiles.map((profile) => (
78	                <option key={profile.id} value={profile.id}>
79	                  {profile.name}
80	                </option>
81	              ))}
82	            </SettingsSelect>
83	            <Button
84	              type="button"
85	              variant="outline"
86	              size="sm"
87	              onClick={() => setProfileManagerOpen(true)}
88	              disabled={profilesBusy}
89	            >
90	              Manage profiles
91	            </Button>
92	          </div>
93	        </SettingsField>
94	        {activeProfile?.description ? (
95	          <SettingsHelpText>{activeProfile.description}</SettingsHelpText>
96	        ) : null}
97	        {profilesError ? <SettingsErrorText>{profilesError}</SettingsErrorText> : null}
98	      </SettingsCard>
99	
100	      <GitSettingsCard
101	        gitSettings={syncSettings}
102	        activeProfileId={activeProfileId}
103	        busy={profilesBusy}
104	        onApply={(next) => updateSyncSettings(next)}
105	      />
106	
107	      <SettingsCard title="SSH key">
108	        {sshPublicKey ? (
109	          <>
110	            <SettingsField label="Public key">
111	              <code className="block break-all rounded bg-muted/50 p-2 text-xs text-foreground select-all">
112	                {sshPublicKey}
113	              </code>
114	            </SettingsField>
115	            <SettingsHelpText>
116	              Add this key to <code>~/.ssh/authorized_keys</code> on your server.
117	            </SettingsHelpText>
118	            <SettingsActionRow>
119	              <Button
